// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkOwnerLoadSnapshot) predicate.WorkOwnerLoadSnapshot {
	return predicate.WorkOwnerLoadSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkOwnerLoadSnapshot) predicate.WorkOwnerLoadSnapshot {
	return predicate.WorkOwnerLoadSnapshot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkOwnerLoadSnapshot) predicate.WorkOwnerLoadSnapshot {
	return predicate.WorkOwnerLoadSnapshot(sql.NotPredicates(p))
}
